          "2. «ـهَا» (-haa) = haar (vrouwelijk enkelvoud, afgeleid van هِيَ).",
          "3. «ـكَ» (-ka) = jouw (mannelijk enkelvoud, afgeleid van أَنْتَ).",
          "4. «ـِي» (-ie) = mijn (afgeleid van أَنَا).",
